#include <cstdio>
#include <bitset>
#include <vector>
#include <unordered_map>
using namespace std;

typedef bitset<128> u128;
typedef long long ll;
const ll mod = 1000000007;

ll powmod(ll a, ll b) {
    ll res = 1;
    a %= mod;
    for (; b; b >>= 1) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
    }
    return res;
}

inline int bit(int n) { return 1 << n; }

inline u128 bitu128(int n) {
    u128 p;
    p[n] = 1;
    return p;
}

const int maxN = 7;
const int max2N = 1 << maxN;
const int maxM = 100;
const int maxS = 64184;
const int sizes[maxN + 1] = {0, 5, 11, 37, 137, 821, 7529, 164184};

struct Hash {
    size_t operator()(const u128& s) const {
        size_t h = 0;
        for (int i = 0; i < 128; ++i) h = h * 2 + s[i];
        return h;
    }
};

vector<u128> bfs;
unordered_map<u128, int, Hash> id;
int nxttt[max2N][maxS];
int match[maxS];

int get_ind(const u128& state) {
    auto it = id.find(state);
    if (it != id.end()) return it->second;
    int idx = (int)bfs.size();
    bfs.push_back(state);
    id[state] = idx;
    return idx;
}

void precalc(int n) {
    int N = bit(n);
    u128 fixed_size[maxN + 1] = {0};
    for (int mask = 0; mask < N; ++mask) {
        int cnt = 0;
        for (int i = 0; i < n; ++i)
            if (mask & bit(i)) ++cnt;
        fixed_size[cnt] |= bitu128(mask);
    }
    bfs.clear();
    id.clear();
    id.reserve(sizes[n] * 2);
    vector<u128> stk;
    get_ind(1);
    stk.push_back(1);
    while (!stk.empty()) {
        u128 state = stk.back();
        stk.pop_back();
        int k = id[state];
        u128 pred_hall[maxN] = {0};
        for (int mask = 0; mask < N; ++mask) {
            if ((state & bitu128(mask)).any()) {
                for (int i = 0; i < n; ++i)
                    pred_hall[i] |= bitu128(mask | bit(i));
            }
        }
        for (int mask = 0; mask < N; ++mask) {
            u128 nxt = state;
            for (int i = 0; i < n; ++i)
                if (mask & bit(i)) nxt |= pred_hall[i];
            auto it = id.find(nxt);
            if (it == id.end()) stk.push_back(nxt);
            nxttt[mask][k] = get_ind(nxt);
        }
        for (int i = n; i >= 0; --i) {
            if ((state & fixed_size[i]).any()) {
                match[k] = i;
                break;
            }
        }
    }
}

ll p[maxN][maxM];
ll prv[maxS];
ll cur[maxS];

ll expectedMaximumMatching(int n, int m) {
    for (int k = 0; k < (int)bfs.size(); ++k) prv[k] = 0;
    prv[0] = 1;
    int N = bit(n);
    for (int j = 0; j < m; ++j) {
        for (int k = 0; k < (int)bfs.size(); ++k) cur[k] = 0;
        for (int mask = 0; mask < N; ++mask) {
            ll prob = 1;
            for (int i = 0; i < n; ++i)
                prob = prob * (mask & bit(i) ? p[i][j] : mod + 1 - p[i][j]) % mod;
            for (int k = 0; k < (int)bfs.size(); ++k)
                cur[nxttt[mask][k]] = (cur[nxttt[mask][k]] + prob * prv[k]) % mod;
        }
        for (int k = 0; k < (int)bfs.size(); ++k) prv[k] = cur[k];
    }
    ll ans = 0;
    for (int k = 0; k < (int)bfs.size(); ++k)
        if (match[k] == n) ans = (ans + prv[k]) % mod;
    return ans;
}

int main() {
    int n, m;
    scanf("%d", &n);
    m = n;
    precalc(n);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            scanf("%lld", &p[i][j]);
            p[i][j] = p[i][j] * powmod(100, mod - 2) % mod;
        }
    ll ans = expectedMaximumMatching(n, m);
    printf("%lld\n", ans);
    return 0;
}
